using System;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;

// Shared uGUI primitives. Decorative graphics never intercept pointer events.
public static class CatUI {
 public static readonly Color Surface=new Color(.075f,.115f,.105f,.98f),Raised=new Color(.14f,.2f,.18f),Ink=new Color(.94f,.91f,.82f),Muted=new Color(.68f,.75f,.7f),Gold=new Color(.87f,.7f,.38f);
 static Font font;public static Font Font=>font!=null?font:font=Font.CreateDynamicFontFromOSFont(new[]{"Microsoft YaHei","SimHei","Arial"},20);
 public static RectTransform Panel(Transform parent,string name,float x,float y,float w,float h,Color? color=null,bool block=false){var g=new GameObject(name,typeof(RectTransform),typeof(Image));g.transform.SetParent(parent,false);var r=g.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=r.pivot=Vector2.up;r.anchoredPosition=new Vector2(x,-y);r.sizeDelta=new Vector2(w,h);var i=g.GetComponent<Image>();i.color=color??Surface;i.raycastTarget=block;return r;}
 public static Text Text(Transform parent,string name,string value,float x,float y,float w,float h,int size=18,Color? color=null){var g=new GameObject(name,typeof(RectTransform),typeof(Text));g.transform.SetParent(parent,false);var r=g.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=r.pivot=Vector2.up;r.anchoredPosition=new Vector2(x,-y);r.sizeDelta=new Vector2(w,h);var t=g.GetComponent<Text>();t.font=Font;t.fontSize=size;t.text=value;t.color=color??Ink;t.raycastTarget=false;t.horizontalOverflow=HorizontalWrapMode.Wrap;t.verticalOverflow=VerticalWrapMode.Truncate;return t;}
 public static Button Button(Transform parent,string name,float x,float y,float w,float h,Action action,bool enabled=true,bool selected=false){var r=Panel(parent,name,x,y,w,h,selected?new Color(.3f,.33f,.21f):Raised,true);var b=r.gameObject.AddComponent<Button>();b.interactable=enabled;b.targetGraphic=r.GetComponent<Image>();var c=b.colors;c.normalColor=Color.white;c.highlightedColor=new Color(1.2f,1.15f,.95f);c.pressedColor=new Color(.75f,.8f,.7f);c.disabledColor=new Color(.4f,.42f,.4f);b.colors=c;Text(r,"Label",name,10,6,w-20,h-9,17,selected?Gold:Ink);b.onClick.AddListener(()=>action());return b;}
 public static Image Icon(Transform parent,string key,float x,float y,float size,HudIconCatalog icons){var r=Panel(parent,"Icon:"+key,x,y,size,size,Color.white);var i=r.GetComponent<Image>();i.sprite=icons.Get(key);i.preserveAspect=true;i.enabled=i.sprite!=null;return i;}
 public static RectTransform Scroll(Transform parent,string name,float x,float y,float w,float h,float contentHeight){var viewport=Panel(parent,name,x,y,w,h,new Color(.04f,.07f,.065f),true);viewport.gameObject.AddComponent<RectMask2D>();var content=new GameObject("Content",typeof(RectTransform)).GetComponent<RectTransform>();content.SetParent(viewport,false);content.anchorMin=content.anchorMax=content.pivot=Vector2.up;content.sizeDelta=new Vector2(w-20,Mathf.Max(h,contentHeight));var scroll=viewport.gameObject.AddComponent<ScrollRect>();scroll.viewport=viewport;scroll.content=content;scroll.horizontal=false;scroll.movementType=ScrollRect.MovementType.Clamped;scroll.scrollSensitivity=30;return content;}
 public static Image Progress(Transform parent,string name,float x,float y,float w,float h,float value,Color color){var bg=Panel(parent,name,x,y,w,h,Raised);var fill=Panel(bg,"Fill",0,0,w*Mathf.Clamp01(value),h,color);return fill.GetComponent<Image>();}
}
